174	    // ---------- 404 / 409 / 422 分支 ----------
175	
176	    @Test
177	    void notFoundConflictAndUnprocessableBranches() throws Exception {
178	        Ctx ctx = newContext();
179	
180	        // 404：频道/素材/授权/明细不存在
181	        createOverride(ctx, "nf-1", "nf1", ctx.newsAsset, ctx.newsGrant, 5, T_1020, T_1030)
182	                .andExpect(status().isOk());
183	        mvc.perform(post("/api/emergency-overrides").contentType(MediaType.APPLICATION_JSON)
184	                        .content(objectMapper.writeValueAsString(overrideBody(
185	                                "nf-2", ctx.key("nf2"), ctx.prefix + "ghost", ctx.newsAsset,
186	                                ctx.newsGrant, 5, T_1020, T_1030))))
187	                .andExpect(status().isNotFound());
188	        mvc.perform(post("/api/emergency-overrides").contentType(MediaType.APPLICATION_JSON)
189	                        .content(objectMapper.writeValueAsString(overrideBody(
190	                                "nf-3", ctx.key("nf3"), ctx.channel, ctx.prefix + "ghost",
191	                                ctx.newsGrant, 5, T_1020, T_1030))))
192	                .andExpect(status().isNotFound());
193	        createOverrideRaw("nf-4", ctx.key("nf4"), ctx.channel, ctx.newsAsset, 999999, 5,
194	                        T_1020, T_1030)
195	                .andExpect(status().isNotFound());
196	        getOverrideRaw(ctx.prefix + "ghost").andExpect(status().isNotFound());
197	        postJson("/api/emergency-overrides/" + ctx.prefix + "ghost/cancel",
198	                        Map.of("requestId", "nf-5"))
199	                .andExpect(status().isNotFound());
200	
201	        // 422：授权不属于该频道
202	        Ctx other = newContext();
203	        createOverrideRaw("nm-1", ctx.key("nm1"), ctx.channel, ctx.newsAsset,
204	                        other.newsGrant, 5, T_1020, T_1030)
205	                .andExpect(status().isUnprocessableEntity())
206	                .andExpect(jsonPath("$.error").value("GRANT_NOT_MATCHED"));
207	        // 422：授权素材不匹配（movie 的授权用于 news 素材）
208	        createOverrideRaw("nm-2", ctx.key("nm2"), ctx.channel, ctx.newsAsset,
209	                        ctx.movieGrant, 5, T_1020, T_1030)
210	                .andExpect(status().isUnprocessableEntity())
211	                .andExpect(jsonPath("$.error").value("GRANT_NOT_MATCHED"));
212	
213	        // 422：授权未完整覆盖区间（授权 10:00-10:20，插播 10:10-10:30）
214	        long shortGrant = createGrant(ctx.channel, ctx.newsAsset,
215	                "2026-09-22T10:00:00.000+08:00", "2026-09-22T10:20:00.000+08:00");
216	        createOverrideRaw("nc-1", ctx.key("nc1"), ctx.channel, ctx.newsAsset,
217	                        shortGrant, 5, "2026-09-22T10:10:00.000+08:00", T_1030)
218	                .andExpect(status().isUnprocessableEntity())
219	                .andExpect(jsonPath("$.error").value("GRANT_NOT_COVERING"));
220	
221	        // 422：保底素材不能用于插播（授权校验前即拒绝）
222	        createOverrideRaw("fb-1", ctx.key("fb1"), ctx.channel, ctx.fallbackAsset,
223	                        ctx.newsGrant, 5, T_1020, T_1030)
224	                .andExpect(status().isUnprocessableEntity())
225	                .andExpect(jsonPath("$.error").value("FALLBACK_ASSET_NOT_GRANTABLE"));
226	
227	        // 422：指定授权已撤销（撤销先提交）
228	        long revokedGrant = createGrant(ctx.channel, ctx.alertAsset, GRANT_FROM, GRANT_TO);
229	        postJson("/api/grants/" + revokedGrant + "/revoke", Map.of("requestId", "rv-g"))
230	                .andExpect(status().isOk());
231	        createOverrideRaw("rv-1", ctx.key("rv1"), ctx.channel, ctx.alertAsset,
232	                        revokedGrant, 5, T_1020, T_1030)
233	                .andExpect(status().isUnprocessableEntity())
234	                .andExpect(jsonPath("$.error").value("GRANT_INVALID"));
235	
236	        // 409：同频道同优先级 ACTIVE 区间重叠（端点相接之外的部分重叠）
237	        createOverrideRaw("ov-2", ctx.key("ov-2"), ctx.channel, ctx.alertAsset,
238	                        ctx.alertGrant, 5, T_1025, T_1035)
239	                .andExpect(status().isConflict())
240	                .andExpect(jsonPath("$.error").value("OVERRIDE_INTERVAL_CONFLICT"));
241	        // 与另一条不同优先级的区间重叠不受影响（已在上面验证 3 级可重叠；这里重叠已有 5 级 nf1）
242	        createOverrideRaw("ov-3", ctx.key("ov-3"), ctx.channel, ctx.alertAsset,
243	                        ctx.alertGrant, 9, T_1025, T_1035)
244	                .andExpect(status().isOk());
245	
246	        // 409：重复 overrideKey
247	        createOverrideRaw("dup-1", ctx.key("nf1"), ctx.channel, ctx.newsAsset,
248	                        ctx.newsGrant, 5, "2026-09-22T15:00:00.000+08:00",
249	                        "2026-09-22T15:10:00.000+08:00")
250	                .andExpect(status().isConflict())
251	                .andExpect(jsonPath("$.error").value("DUPLICATE_OVERRIDE_KEY"));
252	
253	        // 409：取消 ACTIVE 后再次取消
254	        postJson("/api/emergency-overrides/" + ctx.key("nf1") + "/cancel",
255	                        Map.of("requestId", "cancel-nf1"))
256	                .andExpect(status().isOk());
257	        postJson("/api/emergency-overrides/" + ctx.key("nf1") + "/cancel",
258	                        Map.of("requestId", "cancel-nf1-again"))
259	                .andExpect(status().isConflict())
260	                .andExpect(jsonPath("$.error").value("OVERRIDE_NOT_ACTIVE"));
261	    }
262	
263	    // ---------- 幂等 ----------
264	
265	    @Test
266	    void idempotencyReplayChangedParamsFailureAndNoResurrection() throws Exception {
267	        Ctx ctx = newContext();
268	
269	        Map<String, Object> body = overrideBody("idem-1", ctx.key("io"), ctx.channel,
270	                ctx.newsAsset, ctx.newsGrant, 5, T_1020, T_1030);
271	        // 首次成功
272	        postJson("/api/emergency-overrides", body).andExpect(status().isOk());
273	        // 同 requestId 同参数重放：返回首次结果
274	        postJson("/api/emergency-overrides", body)
275	                .andExpect(status().isOk())
276	                .andExpect(jsonPath("$.status").value("ACTIVE"))
277	                .andExpect(jsonPath("$.overrideKey").value(ctx.key("io")));
278	        // 同 requestId 改参数（优先级）：409
279	        postJson("/api/emergency-overrides", overrideBody("idem-1", ctx.key("io"), ctx.channel,
280	                        ctx.newsAsset, ctx.newsGrant, 6, T_1020, T_1030))
281	                .andExpect(status().isConflict())
282	                .andExpect(jsonPath("$.error").value("REQUEST_ID_CONFLICT"));
283	        // 同 requestId 改键：409
284	        postJson("/api/emergency-overrides", overrideBody("idem-1", ctx.key("io2"), ctx.channel,
285	                        ctx.newsAsset, ctx.newsGrant, 5, T_1020, T_1030))
286	                .andExpect(status().isConflict())
287	                .andExpect(jsonPath("$.error").value("REQUEST_ID_CONFLICT"));
288	
289	        // 失败不占 requestId、不占 overrideKey：先因授权不覆盖 422，再用同 requestId 同键成功
290	        long shortGrant = createGrant(ctx.channel, ctx.newsAsset,
291	                "2026-09-22T11:00:00.000+08:00", "2026-09-22T11:20:00.000+08:00");
292	        createOverrideRaw("retry-1", ctx.key("rk"), ctx.channel, ctx.newsAsset, shortGrant, 5,
293	                        "2026-09-22T11:10:00.000+08:00", "2026-09-22T11:30:00.000+08:00")
294	                .andExpect(status().isUnprocessableEntity());
295	        getOverride(ctx, "rk").andExpect(status().isNotFound());
296	        createOverrideRaw("retry-1", ctx.key("rk"), ctx.channel, ctx.newsAsset, ctx.newsGrant, 5,
297	                        "2026-09-22T12:00:00.000+08:00", "2026-09-22T12:10:00.000+08:00")
298	                .andExpect(status().isOk())
299	                .andExpect(jsonPath("$.overrideKey").value(ctx.key("rk")));
300	
301	        // 取消幂等：同 requestId 重放返回首次的 CANCELLED 明细
302	        postJson("/api/emergency-overrides/" + ctx.key("rk") + "/cancel",
303	                        Map.of("requestId", "cancel-rk"))
304	                .andExpect(status().isOk())
305	                .andExpect(jsonPath("$.status").value("CANCELLED"));
306	        postJson("/api/emergency-overrides/" + ctx.key("rk") + "/cancel",
307	                        Map.of("requestId", "cancel-rk"))
308	                .andExpect(status().isOk())
309	                .andExpect(jsonPath("$.status").value("CANCELLED"));
310	        // 同 requestId 用于取消其他插播：409
311	        postJson("/api/emergency-overrides/" + ctx.key("io") + "/cancel",
312	                        Map.of("requestId", "cancel-rk"))
313	                .andExpect(status().isConflict())
314	                .andExpect(jsonPath("$.error").value("REQUEST_ID_CONFLICT"));
315	
316	        // 重放创建不能复活已取消插播：
317	        // 新 requestId 用同键再创建 → 409，明细仍 CANCELLED
318	        createOverride(ctx, "resurrect-1", "rk", ctx.newsAsset, ctx.newsGrant, 5,
319	                        "2026-09-22T12:00:00.000+08:00", "2026-09-22T12:10:00.000+08:00")
320	                .andExpect(status().isConflict())
321	                .andExpect(jsonPath("$.error").value("DUPLICATE_OVERRIDE_KEY"));
322	        getOverride(ctx, "rk").andExpect(jsonPath("$.status").value("CANCELLED"));
323	        // 原创建 requestId 重放只返回历史响应，不改变 CANCELLED 状态
324	        createOverrideRaw("retry-1", ctx.key("rk"), ctx.channel, ctx.newsAsset, ctx.newsGrant, 5,
325	                        "2026-09-22T12:00:00.000+08:00", "2026-09-22T12:10:00.000+08:00")
326	                .andExpect(status().isOk())
327	                .andExpect(jsonPath("$.status").value("ACTIVE"));
328	        getOverride(ctx, "rk").andExpect(jsonPath("$.status").value("CANCELLED"));
329	    }
