522	    /** 发布一段 10:00-11:00 的 movie 节目，作为插播下层的原节目。 */
523	    private void publishProgram(Ctx ctx, String segmentId, String start, String end) throws Exception {
524	        List<Map<String, Object>> segments = new ArrayList<>();
525	        Map<String, Object> segment = new LinkedHashMap<>();
526	        segment.put("id", ctx.prefix + segmentId);
527	        segment.put("assetId", ctx.movieAsset);
528	        segment.put("start", start);
529	        segment.put("end", end);
530	        segments.add(segment);
531	        Map<String, Object> draftBody = new LinkedHashMap<>();
532	        draftBody.put("requestId", "draft-" + ctx.prefix + segmentId);
533	        draftBody.put("expectedDraftVersion", 0);
534	        draftBody.put("segments", segments);
535	        mvc.perform(put("/api/channels/" + ctx.channel + "/drafts/" + DAY)
536	                        .contentType(MediaType.APPLICATION_JSON)
537	                        .content(objectMapper.writeValueAsString(draftBody)))
538	                .andExpect(status().isOk());
539	        postJson("/api/channels/" + ctx.channel + "/drafts/" + DAY + "/publish",
540	                        Map.of("requestId", "pub-" + ctx.prefix + segmentId,
541	                                "draftVersion", 1, "expectedPublishedVersion", 0))
542	                .andExpect(status().isOk());
