        // 同 crawlKey 重放：仍为首次撤销结果
        postJson("/api/emergency-captions/" + ctx.cap("rcap-1") + "/revoke",
                        Map.of("crawlKey", ctx.ck("rrv1")))
                .andExpect(status().isOk())
