                        "2026-09-22T02:25:00Z", "2026-09-22T02:35:00Z", List.of("east"))
                .andExpect(status().isOk());
        // 404 撤销
        postJson("/api/emergency-captions/" + ctx.prefix + "ghost/revoke",
                        Map.of("crawlKey", ctx.ck("rrv404")))
                .andExpect(status().isNotFound());
    }

