    // ---------- 发布主流程：时间片、优先级、快照固化与回执 ----------

    @Test
    void publishFreezesCaptionDecisionsAndReceiptConfirmsSnapshot() throws Exception {
        Ctx ctx = newContext();
        prepareProgram(ctx);
        String tv5 = ctx.approveText("p5", "常规滚动字幕");
        String tv9 = ctx.approveText("p9", "最高优先级插播字幕");

