        postJson("/api/channels/" + ctx.channel + "/drafts/" + DAY + "/publish", Map.of(
                        "requestId", ctx.ck("pub-base"), "draftVersion", 1,
                        "expectedPublishedVersion", 0))
                .andExpect(status().isOk());
