    private String newText(String shortKey, String content) throws Exception {
        Ctx ctx = currentCtx.get();
        String versionId = ctx.tv(shortKey);
        postJson("/api/caption-texts", Map.of(
                        "crawlKey", ctx.ck("txt-" + shortKey), "versionId", versionId, "content", content))
                .andExpect(status().isOk());
        return versionId;
    }

